//! Shell completions: scripts generated by `focal completions`, and the static Bash script
//! in completions/, which completes command names through `focal --commands`.

mod common;

use common::*;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, Output};

const COMMANDS: [&str; 13] = [
    "api",
    "ci-fail",
    "context",
    "diff",
    "files",
    "issues",
    "pr-diff",
    "release-context",
    "search",
    "symbol",
    "tree",
    "web",
    "wip-context",
];

/// Finds `name` on the test process's PATH, like `shutil.which`.
fn which(name: &str) -> Option<PathBuf> {
    let path = std::env::var_os("PATH")?;
    std::env::split_paths(&path)
        .map(|dir| dir.join(name))
        .find(|candidate| candidate.is_file())
}

fn run(tmp: &Path, args: &[&str]) -> Output {
    let env = env(&[
        ("PATH", ""),
        ("HOME", tmp.to_str().unwrap()),
        ("NO_COLOR", "1"),
        ("LC_ALL", "C"),
    ]);
    focal(tmp, &env, args, None)
}

/// Generates the completion script for `shell` and writes it to `tmp/focal.<shell>`.
fn script(tmp: &Path, shell: &str) -> PathBuf {
    let result = run(tmp, &["completions", shell]);
    assert_eq!(result.status.code(), Some(0), "{}", text(&result.stderr));
    assert_eq!(text(&result.stderr), "");
    let path = tmp.join(format!("focal.{shell}"));
    fs::write(&path, &result.stdout).unwrap();
    path
}

/// Sources a Bash completion script with `focal` (and nothing else) on PATH and completes
/// the last word. The function receives the command, current word, and previous word, as
/// `complete -F` passes them, and the candidates come back one per line.
fn complete_bash(
    bash: &Path,
    tmp: &Path,
    script: &Path,
    function: &str,
    words: &[&str],
) -> Vec<String> {
    let bin_dir = tmp.join("bin");
    fs::create_dir_all(&bin_dir).unwrap();
    let link = bin_dir.join("focal");
    if !link.exists() {
        std::os::unix::fs::symlink(bin(), &link).unwrap();
    }
    let program = format!(
        "source \"$1\"; shift; COMP_WORDS=(\"$@\"); COMP_CWORD=$(($# - 1)); \
         {function} focal \"${{COMP_WORDS[COMP_CWORD]}}\" \"${{COMP_WORDS[COMP_CWORD - 1]}}\"; \
         for c in \"${{COMPREPLY[@]}}\"; do echo \"$c\"; done"
    );
    let result = Command::new(bash)
        .args(["--norc", "--noprofile", "-c", &program, "bash"])
        .arg(script)
        .arg("focal")
        .args(words)
        .current_dir(tmp)
        .env_clear()
        .env("PATH", &bin_dir)
        .env("HOME", tmp)
        .env("LC_ALL", "C")
        .output()
        .unwrap();
    assert!(result.status.success(), "{}", text(&result.stderr));
    text(&result.stdout)
        .split_whitespace()
        .map(str::to_owned)
        .collect()
}

fn check_names_every_public_command(shell: &str) {
    let tmp = tempfile::tempdir().unwrap();
    let contents = fs::read_to_string(script(tmp.path(), shell)).unwrap();
    for name in COMMANDS {
        assert!(contents.contains(name), "{name}");
    }
    assert!(!contents.contains("completions"));
    for flag in ["--staged", "--cached", "--thick", "--modified", "--repo"] {
        assert!(contents.contains(flag), "{flag}");
    }
}

#[test]
fn generated_script_names_every_public_command_bash() {
    check_names_every_public_command("bash");
}

#[test]
fn generated_script_names_every_public_command_zsh() {
    check_names_every_public_command("zsh");
}

#[test]
fn generated_bash_script_parses() {
    let Some(bash) = which("bash") else {
        eprintln!("skipped: bash is not installed");
        return;
    };
    let tmp = tempfile::tempdir().unwrap();
    let path = script(tmp.path(), "bash");
    let result = Command::new(bash).arg("-n").arg(&path).output().unwrap();
    assert!(result.status.success(), "{}", text(&result.stderr));
}

#[test]
fn generated_zsh_script_parses() {
    let Some(zsh) = which("zsh") else {
        eprintln!("skipped: zsh is not installed");
        return;
    };
    let tmp = tempfile::tempdir().unwrap();
    let path = script(tmp.path(), "zsh");
    let result = Command::new(zsh).arg("-n").arg(&path).output().unwrap();
    assert!(result.status.success(), "{}", text(&result.stderr));
    assert!(
        fs::read_to_string(&path)
            .unwrap()
            .starts_with("#compdef focal\n")
    );
}

fn check_bash_completes(words: &[&str], expected: &[&str]) {
    let Some(bash) = which("bash") else {
        eprintln!("skipped: bash is not installed");
        return;
    };
    let tmp = tempfile::tempdir().unwrap();
    let path = script(tmp.path(), "bash");
    let mut candidates = complete_bash(&bash, tmp.path(), &path, "_focal", words);
    // An empty word also offers the top-level flags; the order follows the parser.
    if words.last().unwrap().is_empty() {
        candidates.retain(|c| !c.starts_with('-'));
    }
    candidates.sort();
    assert_eq!(candidates, expected, "words {words:?}");
}

#[test]
fn generated_bash_script_completes_commands() {
    check_bash_completes(&[""], &COMMANDS);
}

#[test]
fn generated_bash_script_completes_prefix() {
    check_bash_completes(&["wi"], &["wip-context"]);
}

#[test]
fn generated_bash_script_completes_diff_flag() {
    check_bash_completes(&["diff", "--st"], &["--staged"]);
}

#[test]
fn generated_bash_script_completes_files_flag() {
    check_bash_completes(&["files", "--mo"], &["--modified"]);
}

#[test]
fn generated_bash_script_completes_after_repo() {
    check_bash_completes(&["--repo", "https://github.com/o/r", "tr"], &["tree"]);
}

fn check_unknown_shell_is_rejected(shell: &str) {
    let tmp = tempfile::tempdir().unwrap();
    let result = run(tmp.path(), &["completions", shell]);
    assert_eq!(result.status.code(), Some(1));
    assert_eq!(text(&result.stdout), "");
    let err = text(&result.stderr);
    assert!(
        err.contains(&format!("unsupported shell '{shell}'")),
        "{err}"
    );
}

#[test]
fn unknown_shell_is_rejected_fish() {
    check_unknown_shell_is_rejected("fish");
}

#[test]
fn unknown_shell_is_rejected_empty() {
    check_unknown_shell_is_rejected("");
}

fn check_static_bash_script(word: &str, expected: &[&str]) {
    let Some(bash) = which("bash") else {
        eprintln!("skipped: bash is not installed");
        return;
    };
    let tmp = tempfile::tempdir().unwrap();
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("completions/focal.bash");
    let candidates = complete_bash(&bash, tmp.path(), &path, "_focal_completions", &[word]);
    assert_eq!(candidates, expected, "word {word:?}");
}

#[test]
fn legacy_bash_script_completes_through_commands_flag_empty() {
    check_static_bash_script("", &COMMANDS);
}

#[test]
fn legacy_bash_script_completes_through_commands_flag_prefix() {
    check_static_bash_script("pr", &["pr-diff"]);
}
